function validate([mat, r, c]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 100) return 'Each row needs 1 to 100 values.';
  for (const row of mat) {
    if (row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is a whole number from -1000 to 1000.';
  }
  if (!Number.isInteger(r) || r < 1 || r > 300) return 'r is a whole number from 1 to 300.';
  if (!Number.isInteger(c) || c < 1 || c > 300) return 'c is a whole number from 1 to 300.';
  return null;
}

