function matrixReshape(mat, r, c) {
  // Flatten everything into one list, then cut it into rows of length c.
  const flat = [];
  for (const line of mat) for (const v of line) flat.push(v);
  if (flat.length !== r * c) return mat;
  const out = [];
  while (out.length < r) out.push(flat.splice(0, c));
  return out;
}

