function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const m = large ? 50 + pick(51) : 1 + pick(4);
  const n = large ? 50 + pick(51) : 1 + pick(4);
  const span = large || rand() < 0.5 ? 1000 : 5;
  const mat = Array.from({ length: m }, () => Array.from({ length: n }, () => pick(2 * span + 1) - span));
  const total = m * n;
  // Mostly pick a legal shape (a divisor pair within 300), sometimes an illegal one.
  const divisors = [];
  for (let d = 1; d <= Math.min(300, total); d++) if (total % d === 0 && total / d <= 300) divisors.push(d);
  if (rand() < 0.75 && divisors.length) {
    const r = divisors[pick(divisors.length)];
    return [mat, r, total / r];
  }
  let r = 1 + pick(large ? 300 : 6);
  let c = 1 + pick(large ? 300 : 6);
  if (r * c === total) c = c === 300 ? c - 1 : c + 1;
  return [mat, r, c];
}
